int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    if (!g || drive < 0 || drive >= N_DRIVE) {
        return -EINVAL;
    }

    if (type == FLPARAM_USER) {
        if (!capable(CAP_SYS_ADMIN))
            return -EPERM;

        if (lock_fdc(0)) {
            return -EINTR;
        }

        if (FDC(drive)->track != 0) {
            unlock_fdc(0);
            return -EINTR;
        }

        if (g->track > 128 || g->head > 2 || g->sector > 32 || g->stretch > 1) {
            unlock_fdc(0);
            return -EINVAL;
        }

        FDC(drive)->max_track = g->track;
        FDC(drive)->max_head = g->head;
        FDC(drive)->max_sector = g->sector;
        FDC(drive)->stretch = g->stretch;
    } else {
        if (cmd == SETGEOMETRY) {
            if (g->track == 0 || g->head == 0 || g->sector == 0) {
                return -EINVAL;
            }

            if (lock_fdc(0)) {
                return -EINTR;
            }

            if (FDC(drive)->track != 0) {
                unlock_fdc(0);
                return -EINTR;
            }

            FDC(drive)->max_track = g->track;
            FDC(drive)->max_head = g->head;
            FDC(drive)->max_sector = g->sector;
            FDC(drive)->stretch = g->stretch;
        } else {
            return -EINVAL;
        }
    }

    unlock_fdc(0);
    return 0;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    if (!g || drive < 0 || drive >= N_DRIVE || type < 0)
        return -EINVAL;

    if (type == FLPARAM_USER) {
        if (!capable(CAP_SYS_ADMIN))
            return -EPERM;

        if (lock_fdc(0)) /* Lock the floppy disk controller */
            return -EINTR;

        if (!g->sector || !g->head || !g->track || g->stretch < 0)
            return -EINVAL;

        /* Update floppy type and sizes */
        current_type[drive] = *g;
        update_drive_params(drive);
    } else {
        if (cmd == FD_SETFMT) {
            if (invalidate_drive(drive))
                return -EINVAL;
            current_sectors[drive] = g->sector;
            current_heads[drive] = g->head;
        }
    }

    return 0;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    int ret = 0;

    if (!g || drive < 0 || drive >= N_DRIVE) {
        return -EINVAL;
    }

    if (type == FLOPPY_USER_DEFINED) {
        if (!capable(CAP_SYS_ADMIN)) {
            return -EPERM;
        }

        if (lock_floppy()) {
            return -EINTR;
        }

        if (g->sector < 1 || g->head < 1 || g->track < 1 || g->stretch < 0) {
            unlock_floppy();
            return -EINVAL;
        }

        floppy_type[drive] = g;
        update_drive_params(drive);
        unlock_floppy();
    } else {
        switch (cmd) {
            case FDC_SET_GEOMETRY:
                if (g->sector < 1 || g->head < 1 || g->track < 1 || g->stretch < 0) {
                    return -EINVAL;
                }

                if (lock_floppy()) {
                    return -EINTR;
                }

                current_drive_geometry[drive] = *g;
                unlock_floppy();
                break;

            case FDC_RESET_GEOMETRY:
                if (lock_floppy()) {
                    return -EINTR;
                }

                reset_drive_geometry(drive);
                unlock_floppy();
                break;

            default:
                return -EINVAL;
        }
    }

    return ret;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev)
{
    int ret = 0;

    /* Sanity checks on geometry parameters */
    if (!g || g->sector <= 0 || g->head <= 0 || g->track <= 0 || g->stretch <= 0) {
        return -EINVAL;
    }

    /* Check for user-defined geometry */
    if (type == FLOPPY_TYPE_USER) {
        /* Check for administrative permissions */
        if (!capable(CAP_SYS_ADMIN)) {
            return -EPERM;
        }

        /* Lock the floppy disk controller */
        if (!mutex_trylock(&floppy_mutex)) {
            return -EINTR;
        }

        /* Update floppy type and sizes */
        floppy_type[drive] = g;
        update_floppy_sizes(drive, g);
    } else {
        /* Non-user-defined geometry */
        switch (cmd) {
        case SETGEOM:
            /* Invalidate drive and update current parameters */
            invalidate_drive(drive);
            current_geometry[drive] = *g;
            break;
        case CLEARGEOM:
            /* Clear geometry data */
            clear_geometry(drive);
            break;
        default:
            ret = -EINVAL;
            break;
        }
    }

    return ret;
}

int set_floppy_geometry(unsigned int cmd, struct floppy_struct *g, int drive, int type, struct block_device *bdev) {
    int ret = 0;

    if (!g || drive < 0 || drive >= N_DRIVE)
        return -EINVAL;

    if (type == UDF_FLPY) {
        if (!capable(CAP_SYS_ADMIN))
            return -EPERM;

        if (lock_fdc(drive))
            return -EINTR;

        /* Update floppy type and sizes */
        update_floppy_type(drive, g);
        set_sizes(bdev, g);
        unlock_fdc(drive);
    } else {
        if (cmd == SETFLOPPY) {
            if (invalid_drive(drive))
                return -EINVAL;
            update_current_geometry(drive, g);
        } else {
            ret = handle_special_geometry_command(cmd, drive, g);
            if (ret < 0)
                return ret;
        }
    }

    return ret;
}
